using MediatR;using Microsoft.AspNetCore.Mvc;using WhatsBiz.Api.Authorization;using WhatsBiz.Application.Features.Dashboard;using WhatsBiz.SharedKernel;
namespace WhatsBiz.Api.Controllers;[ApiController,Route("api/dashboard")]public sealed class DashboardController(ISender sender):ControllerBase{private static DashboardRange Range(DateTimeOffset?from,DateTimeOffset?to,bool refresh)=>new(from,to,refresh);[HttpGet("summary"),HasPermission(Permissions.Dashboard.View)]public Task<DashboardSummaryDto>Summary([FromQuery]DateTimeOffset?from,[FromQuery]DateTimeOffset?to,[FromQuery]bool refresh,CancellationToken token)=>sender.Send(new GetDashboardSummary(Range(from,to,refresh)),token);[HttpGet("sales"),HasPermission(Permissions.Dashboard.Analytics)]public Task<SalesAnalyticsDto>Sales([FromQuery]DateTimeOffset?from,[FromQuery]DateTimeOffset?to,[FromQuery]bool refresh,CancellationToken token)=>sender.Send(new GetSalesAnalytics(Range(from,to,refresh)),token);[HttpGet("purchase"),HasPermission(Permissions.Dashboard.Analytics)]public Task<PurchaseAnalyticsDto>Purchase([FromQuery]DateTimeOffset?from,[FromQuery]DateTimeOffset?to,[FromQuery]bool refresh,CancellationToken token)=>sender.Send(new GetPurchaseAnalytics(Range(from,to,refresh)),token);[HttpGet("inventory"),HasPermission(Permissions.Dashboard.View)]public Task<InventoryAnalyticsDto>Inventory([FromQuery]bool refresh,CancellationToken token)=>sender.Send(new GetInventoryAnalytics(refresh),token);[HttpGet("customers"),HasPermission(Permissions.Dashboard.View)]public Task<CustomerAnalyticsDto>Customers([FromQuery]DateTimeOffset?from,[FromQuery]DateTimeOffset?to,[FromQuery]bool refresh,CancellationToken token)=>sender.Send(new GetCustomerAnalytics(Range(from,to,refresh)),token);[HttpGet("suppliers"),HasPermission(Permissions.Dashboard.View)]public Task<SupplierAnalyticsDto>Suppliers([FromQuery]DateTimeOffset?from,[FromQuery]DateTimeOffset?to,[FromQuery]bool refresh,CancellationToken token)=>sender.Send(new GetSupplierAnalytics(Range(from,to,refresh)),token);[HttpGet("finance"),HasPermission(Permissions.Dashboard.View)]public Task<FinanceAnalyticsDto>Finance([FromQuery]DateTimeOffset?from,[FromQuery]DateTimeOffset?to,[FromQuery]bool refresh,CancellationToken token)=>sender.Send(new GetFinanceAnalytics(Range(from,to,refresh)),token);[HttpGet("notifications"),HasPermission(Permissions.Dashboard.View)]public Task<IReadOnlyCollection<DashboardNotificationDto>>Notifications([FromQuery]bool refresh,CancellationToken token)=>sender.Send(new GetDashboardNotifications(refresh),token);}
